import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Register-blocked tiled direct 2D convolution (NCHW, contiguous, float32).
// Each CTA computes a 32x64 output tile for 8 consecutive output channels (OC-blocked); each of 256 threads computes 8x2x4 outputs (register-blocked over 2 output rows).
// Input tiles (halo included) and the 8-OC weight tile are staged cooperatively in shared memory per input channel (double-buffered cp.async).
.extern .shared .align 16 .b8 smem[];
.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 has_bias,
    .param .u32 OC,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 IC,
    .param .u32 H,
    .param .u32 W,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 in_tile_h,
    .param .u32 in_tile_w
)
{
    .reg .pred %p<32>;
    .reg .b32  %r<72>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<96>;
    mov.u32 %r40, 32;                      // TILE_H
    mov.u32 %r46, 64;                      // TILE_W
    mov.u32 %r41, 256;                     // blockDim.x
    mov.u32 %r0, %tid.x;                   // tid
    mov.u32 %r67, 16;                      // thread row groups (TILE_H/2) and col groups (TILE_W/4)
    div.u32 %r1, %r0, %r67;                // th = tid / 16
    rem.u32 %r2, %r0, %r67;                // tw = tid % 16 (column group)
    mov.u32 %r3, %ctaid.x;                 // 64-wide tile column
    mov.u32 %r4, %ctaid.y;                 // 16-high tile row
    mov.u32 %r5, %ctaid.z;                 // b*OCG + oc_group
    ld.param.u32 %r6, [OC];
    add.u32 %r57, %r6, 7;
    shr.u32 %r57, %r57, 3;                 // OCG = ceil(OC/8)
    rem.u32 %r58, %r5, %r57;               // oc group
    div.u32 %r8, %r5, %r57;                // b
    shl.b32 %r7, %r58, 3;                  // oc_base = oc_group*8
    add.u32 %r59, %r7, 1;
    setp.lt.u32 %p17, %r59, %r6;           // oc lane 1 valid
    add.u32 %r59, %r7, 2;
    setp.lt.u32 %p18, %r59, %r6;           // oc lane 2 valid
    add.u32 %r59, %r7, 3;
    setp.lt.u32 %p19, %r59, %r6;           // oc lane 3 valid
    add.u32 %r59, %r7, 4;
    setp.lt.u32 %p20, %r59, %r6;           // oc lane 4 valid
    add.u32 %r59, %r7, 5;
    setp.lt.u32 %p21, %r59, %r6;           // oc lane 5 valid
    add.u32 %r59, %r7, 6;
    setp.lt.u32 %p22, %r59, %r6;           // oc lane 6 valid
    add.u32 %r59, %r7, 7;
    setp.lt.u32 %p23, %r59, %r6;           // oc lane 7 valid
    ld.param.u32 %r9, [OH];
    ld.param.u32 %r10, [OW];
    mad.lo.u32 %r11, %r4, %r40, %r1;       // oh
    mul.lo.u32 %r51, %r2, 4;               // column-group base inside tile
    mad.lo.u32 %r12, %r3, %r46, %r51;      // ow base for 4 outputs
    setp.lt.u32 %p0, %r11, %r9;            // row valid
    add.u32 %r59, %r11, 16;
    setp.lt.u32 %p29, %r59, %r9;           // row-2 valid (oh+16 < OH)
    add.u32 %r47, %r12, 0;
    add.u32 %r48, %r12, 1;
    add.u32 %r49, %r12, 2;
    add.u32 %r50, %r12, 3;
    setp.lt.u32 %p1, %r47, %r10;
    and.pred  %p13, %p0, %p1;
    setp.lt.u32 %p1, %r48, %r10;
    and.pred  %p14, %p0, %p1;
    setp.lt.u32 %p1, %r49, %r10;
    and.pred  %p15, %p0, %p1;
    setp.lt.u32 %p1, %r50, %r10;
    and.pred  %p16, %p0, %p1;
    ld.param.u32 %r13, [stride_h];
    ld.param.u32 %r14, [stride_w];
    ld.param.u32 %r15, [pad_h];
    ld.param.u32 %r16, [pad_w];
    mul.lo.u32 %r17, %r4, %r40;
    mul.lo.u32 %r17, %r17, %r13;
    sub.s32    %r17, %r17, %r15;           // ih0 signed
    mul.lo.u32 %r18, %r3, %r46;
    mul.lo.u32 %r18, %r18, %r14;
    sub.s32    %r18, %r18, %r16;           // iw0 signed
    ld.param.u32 %r19, [IC];
    ld.param.u32 %r20, [H];
    ld.param.u32 %r21, [W];
    ld.param.u32 %r22, [KH];
    ld.param.u32 %r23, [KW];
    ld.param.u32 %r24, [dil_h];
    ld.param.u32 %r25, [dil_w];
    ld.param.u32 %r26, [in_tile_h];
    ld.param.u32 %r27, [in_tile_w];
    mul.lo.u32 %r28, %r26, %r27;           // tile_size
    mul.lo.u32 %r56, %r19, %r22;
    mul.lo.u32 %r56, %r56, %r23;           // IC*KH*KW (weight oc stride)
    mul.lo.u32 %r68, %r22, %r23;           // KH*KW
    shl.b32    %r69, %r68, 3;              // weight-tile floats per channel (8 OC lanes)
    cvt.u64.u32 %rd15, %r56;
    shl.b64     %rd15, %rd15, 2;           // weight oc stride (bytes)
    mul.lo.u32 %r60, %r9, %r10;            // OH*OW
    cvt.u64.u32 %rd16, %r60;
    shl.b64     %rd16, %rd16, 2;           // output oc stride (bytes)
    mul.lo.u32  %r66, %r13, %r27;          // sh*in_tile_w
    shl.b32     %r66, %r66, 4;             // *16 rows (elements)
    cvt.u64.u32 %rd20, %r66;
    shl.b64     %rd20, %rd20, 2;           // row-2 smem byte offset
    cvt.u64.u32 %rd21, %r10;
    shl.b64     %rd21, %rd21, 6;           // row-2 output byte offset (16*OW*4)
    mov.u64 %rd0, smem;
    mov.f32 %f0, 0f00000000;               // acc oc lane0 col0
    mov.f32 %f1, 0f00000000;               // acc oc lane0 col1
    mov.f32 %f2, 0f00000000;               // acc oc lane0 col2
    mov.f32 %f3, 0f00000000;               // acc oc lane0 col3
    mov.f32 %f8, 0f00000000;               // acc oc lane1 col0
    mov.f32 %f9, 0f00000000;               // acc oc lane1 col1
    mov.f32 %f10, 0f00000000;              // acc oc lane1 col2
    mov.f32 %f11, 0f00000000;              // acc oc lane1 col3
    mov.f32 %f12, 0f00000000;              // acc oc lane2 col0
    mov.f32 %f13, 0f00000000;              // acc oc lane2 col1
    mov.f32 %f14, 0f00000000;              // acc oc lane2 col2
    mov.f32 %f15, 0f00000000;              // acc oc lane2 col3
    mov.f32 %f16, 0f00000000;              // acc oc lane3 col0
    mov.f32 %f17, 0f00000000;              // acc oc lane3 col1
    mov.f32 %f18, 0f00000000;              // acc oc lane3 col2
    mov.f32 %f19, 0f00000000;              // acc oc lane3 col3
    mov.f32 %f24, 0f00000000;              // acc oc lane4 col0
    mov.f32 %f25, 0f00000000;              // acc oc lane4 col1
    mov.f32 %f26, 0f00000000;              // acc oc lane4 col2
    mov.f32 %f27, 0f00000000;              // acc oc lane4 col3
    mov.f32 %f28, 0f00000000;              // acc oc lane5 col0
    mov.f32 %f29, 0f00000000;              // acc oc lane5 col1
    mov.f32 %f30, 0f00000000;              // acc oc lane5 col2
    mov.f32 %f31, 0f00000000;              // acc oc lane5 col3
    mov.f32 %f32, 0f00000000;              // acc oc lane6 col0
    mov.f32 %f33, 0f00000000;              // acc oc lane6 col1
    mov.f32 %f34, 0f00000000;              // acc oc lane6 col2
    mov.f32 %f35, 0f00000000;              // acc oc lane6 col3
    mov.f32 %f36, 0f00000000;              // acc oc lane7 col0
    mov.f32 %f37, 0f00000000;              // acc oc lane7 col1
    mov.f32 %f38, 0f00000000;              // acc oc lane7 col2
    mov.f32 %f39, 0f00000000;              // acc oc lane7 col3
    mov.f32 %f45, 0f00000000;              // acc row2 oc lane0 col0
    mov.f32 %f46, 0f00000000;              // acc row2 oc lane0 col1
    mov.f32 %f47, 0f00000000;              // acc row2 oc lane0 col2
    mov.f32 %f48, 0f00000000;              // acc row2 oc lane0 col3
    mov.f32 %f49, 0f00000000;              // acc row2 oc lane1 col0
    mov.f32 %f50, 0f00000000;              // acc row2 oc lane1 col1
    mov.f32 %f51, 0f00000000;              // acc row2 oc lane1 col2
    mov.f32 %f52, 0f00000000;              // acc row2 oc lane1 col3
    mov.f32 %f53, 0f00000000;              // acc row2 oc lane2 col0
    mov.f32 %f54, 0f00000000;              // acc row2 oc lane2 col1
    mov.f32 %f55, 0f00000000;              // acc row2 oc lane2 col2
    mov.f32 %f56, 0f00000000;              // acc row2 oc lane2 col3
    mov.f32 %f57, 0f00000000;              // acc row2 oc lane3 col0
    mov.f32 %f58, 0f00000000;              // acc row2 oc lane3 col1
    mov.f32 %f59, 0f00000000;              // acc row2 oc lane3 col2
    mov.f32 %f60, 0f00000000;              // acc row2 oc lane3 col3
    mov.f32 %f61, 0f00000000;              // acc row2 oc lane4 col0
    mov.f32 %f62, 0f00000000;              // acc row2 oc lane4 col1
    mov.f32 %f63, 0f00000000;              // acc row2 oc lane4 col2
    mov.f32 %f64, 0f00000000;              // acc row2 oc lane4 col3
    mov.f32 %f65, 0f00000000;              // acc row2 oc lane5 col0
    mov.f32 %f66, 0f00000000;              // acc row2 oc lane5 col1
    mov.f32 %f67, 0f00000000;              // acc row2 oc lane5 col2
    mov.f32 %f68, 0f00000000;              // acc row2 oc lane5 col3
    mov.f32 %f69, 0f00000000;              // acc row2 oc lane6 col0
    mov.f32 %f70, 0f00000000;              // acc row2 oc lane6 col1
    mov.f32 %f71, 0f00000000;              // acc row2 oc lane6 col2
    mov.f32 %f72, 0f00000000;              // acc row2 oc lane6 col3
    mov.f32 %f73, 0f00000000;              // acc row2 oc lane7 col0
    mov.f32 %f74, 0f00000000;              // acc row2 oc lane7 col1
    mov.f32 %f75, 0f00000000;              // acc row2 oc lane7 col2
    mov.f32 %f76, 0f00000000;              // acc row2 oc lane7 col3
    mov.f32 %f21, 0f00000000;              // weight lane1 (stays 0 if oc OOB)
    mov.f32 %f22, 0f00000000;              // weight lane2 (stays 0 if oc OOB)
    mov.f32 %f23, 0f00000000;              // weight lane3 (stays 0 if oc OOB)
    mov.f32 %f40, 0f00000000;              // weight lane4 (stays 0 if oc OOB)
    mov.f32 %f41, 0f00000000;              // weight lane5 (stays 0 if oc OOB)
    mov.f32 %f42, 0f00000000;              // weight lane6 (stays 0 if oc OOB)
    mov.f32 %f43, 0f00000000;              // weight lane7 (stays 0 if oc OOB)
    mov.u32 %r29, 0;                       // ic
    // ---- cp.async double-buffered input-tile pipeline (sm_80+) ----
    setp.eq.u32 %p28, %r19, 0;
    @%p28 bra STORE;                     // IC == 0: nothing to accumulate
    mov.u64 %rd23, smem;                 // shared base (u64)
    mov.u32 %r63, smem;                  // shared base (u32, for cp.async dst)
    shl.b32 %r42, %r28, 2;               // input tile bytes
    add.u32 %r70, %r42, 15;
    and.b32 %r70, %r70, 0xFFFFFFF0;      // weight-tile offset within buffer (16B aligned)
    cvt.u64.u32 %rd9, %r70;
    shl.b32 %r71, %r69, 2;               // weight-tile bytes
    add.u32 %r42, %r70, %r71;
    add.u32 %r42, %r42, 15;
    and.b32 %r42, %r42, 0xFFFFFFF0;      // per-buffer stride = align16(wt_off + wt_bytes)
    mov.u32 %r64, 0;                     // current compute buffer offset (bytes)
    // Prologue: asynchronously stage input tile for ic = 0 into buffer 0
    mov.u32 %r61, 0;                     // channel to stage
    mov.u32 %r62, %r63;                  // staging buffer base (buffer 0)
    mov.u32 %r30, %r0;                   // cooperative idx
STAGE0_LOOP:
    setp.ge.u32 %p4, %r30, %r28;
    @%p4 bra STAGE0_DONE;
    div.u32 %r31, %r30, %r27;              // ith
    rem.u32 %r32, %r30, %r27;              // itw
    add.s32 %r33, %r17, %r31;              // ih
    add.s32 %r34, %r18, %r32;              // iw
    setp.lt.s32 %p5, %r33, 0;
    setp.ge.s32 %p6, %r33, %r20;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r34, 0;
    or.pred  %p7, %p7, %p8;
    setp.ge.s32 %p9, %r34, %r21;
    or.pred  %p7, %p7, %p9;                // p7 = out of bounds
    mad.lo.u32 %r35, %r8, %r19, %r61;
    mad.lo.u32 %r35, %r35, %r20, %r33;
    mad.lo.u32 %r35, %r35, %r21, %r34;
    selp.b32  %r35, 0, %r35, %p7;          // clamp OOB address (no bytes read)
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [in_ptr];
    add.u64     %rd2, %rd2, %rd1;
    selp.b32    %r36, 0, 4, %p7;           // src-size 0 -> zero-fill padding
    shl.b32     %r65, %r30, 2;
    add.u32     %r65, %r65, %r62;
    cp.async.ca.shared.global [%r65], [%rd2], 4, %r36;
    add.u32 %r30, %r30, %r41;
    bra STAGE0_LOOP;
STAGE0_DONE:
    // ---- stage 8-OC weight tile for this channel: layout (kh*KW+kw)*8 + oc_lane ----
    mad.lo.u32 %r33, %r7, %r19, %r61;      // oc_base*IC + ic
    mul.lo.u32 %r33, %r33, %r68;           // * KH*KW -> weight base element
    mov.u32 %r30, %r0;                     // widx
WSTAGE0_LOOP:
    setp.ge.u32 %p4, %r30, %r69;
    @%p4 bra WSTAGE0_DONE;
    shr.u32 %r31, %r30, 3;                 // kh*KW+kw
    and.b32 %r32, %r30, 7;                 // oc lane
    add.u32 %r34, %r7, %r32;               // oc
    setp.ge.u32 %p5, %r34, %r6;            // oc invalid (zero-fill lane)
    mad.lo.u32 %r35, %r32, %r56, %r31;     // lane*IC*KH*KW + (kh*KW+kw)
    add.u32 %r35, %r35, %r33;
    selp.b32  %r35, 0, %r35, %p5;          // clamp OOB lane address
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [wt_ptr];
    add.u64     %rd2, %rd2, %rd1;
    selp.b32    %r36, 0, 4, %p5;           // src-size 0 -> zero-fill OOB lane
    shl.b32     %r65, %r30, 2;
    add.u32     %r65, %r65, %r70;          // weight-tile offset within buffer
    add.u32     %r65, %r65, %r62;
    cp.async.ca.shared.global [%r65], [%rd2], 4, %r36;
    add.u32 %r30, %r30, %r41;
    bra WSTAGE0_LOOP;
WSTAGE0_DONE:
    cp.async.commit_group;
LOOP_IC:
    // Asynchronously stage the NEXT input tile into the other buffer,
    // then wait only until the CURRENT tile is resident (overlap load/compute).
    add.u32 %r61, %r29, 1;
    setp.ge.u32 %p28, %r61, %r19;
    @%p28 bra NO_STAGE;
    xor.b32 %r65, %r64, %r42;              // next buffer offset
    add.u32 %r62, %r63, %r65;              // staging buffer base
    mov.u32 %r30, %r0;                     // cooperative idx
STAGE1_LOOP:
    setp.ge.u32 %p4, %r30, %r28;
    @%p4 bra STAGE1_DONE;
    div.u32 %r31, %r30, %r27;              // ith
    rem.u32 %r32, %r30, %r27;              // itw
    add.s32 %r33, %r17, %r31;              // ih
    add.s32 %r34, %r18, %r32;              // iw
    setp.lt.s32 %p5, %r33, 0;
    setp.ge.s32 %p6, %r33, %r20;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r34, 0;
    or.pred  %p7, %p7, %p8;
    setp.ge.s32 %p9, %r34, %r21;
    or.pred  %p7, %p7, %p9;                // p7 = out of bounds
    mad.lo.u32 %r35, %r8, %r19, %r61;
    mad.lo.u32 %r35, %r35, %r20, %r33;
    mad.lo.u32 %r35, %r35, %r21, %r34;
    selp.b32  %r35, 0, %r35, %p7;          // clamp OOB address (no bytes read)
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [in_ptr];
    add.u64     %rd2, %rd2, %rd1;
    selp.b32    %r36, 0, 4, %p7;           // src-size 0 -> zero-fill padding
    shl.b32     %r65, %r30, 2;
    add.u32     %r65, %r65, %r62;
    cp.async.ca.shared.global [%r65], [%rd2], 4, %r36;
    add.u32 %r30, %r30, %r41;
    bra STAGE1_LOOP;
STAGE1_DONE:
    // ---- stage 8-OC weight tile for this channel: layout (kh*KW+kw)*8 + oc_lane ----
    mad.lo.u32 %r33, %r7, %r19, %r61;      // oc_base*IC + ic
    mul.lo.u32 %r33, %r33, %r68;           // * KH*KW -> weight base element
    mov.u32 %r30, %r0;                     // widx
WSTAGE1_LOOP:
    setp.ge.u32 %p4, %r30, %r69;
    @%p4 bra WSTAGE1_DONE;
    shr.u32 %r31, %r30, 3;                 // kh*KW+kw
    and.b32 %r32, %r30, 7;                 // oc lane
    add.u32 %r34, %r7, %r32;               // oc
    setp.ge.u32 %p5, %r34, %r6;            // oc invalid (zero-fill lane)
    mad.lo.u32 %r35, %r32, %r56, %r31;     // lane*IC*KH*KW + (kh*KW+kw)
    add.u32 %r35, %r35, %r33;
    selp.b32  %r35, 0, %r35, %p5;          // clamp OOB lane address
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [wt_ptr];
    add.u64     %rd2, %rd2, %rd1;
    selp.b32    %r36, 0, 4, %p5;           // src-size 0 -> zero-fill OOB lane
    shl.b32     %r65, %r30, 2;
    add.u32     %r65, %r65, %r70;          // weight-tile offset within buffer
    add.u32     %r65, %r65, %r62;
    cp.async.ca.shared.global [%r65], [%rd2], 4, %r36;
    add.u32 %r30, %r30, %r41;
    bra WSTAGE1_LOOP;
WSTAGE1_DONE:
    cp.async.commit_group;
    cp.async.wait_group 1;                 // current tile ready (next in flight)
    bra STAGE_SYNC;
NO_STAGE:
    cp.async.wait_group 0;                 // last tile: drain all groups
STAGE_SYNC:
    bar.sync 0;
    cvt.u64.u32 %rd22, %r64;
    add.u64 %rd0, %rd23, %rd22;            // smem base of current buffer
    add.u64 %rd10, %rd0, %rd9;             // smem weight-tile base of current buffer
    mov.u32 %r36, 0;                       // kh
LOOP_KH:
    setp.ge.u32 %p10, %r36, %r22;
    @%p10 bra COMPUTE_DONE;
    mul.lo.u32 %r37, %r1, %r13;            // th*stride_h
    mad.lo.u32 %r37, %r36, %r24, %r37;     // ih_l
    mov.u32 %r38, 0;                       // kw
LOOP_KW:
    setp.ge.u32 %p11, %r38, %r23;
    @%p11 bra NEXT_KH;
    mul.lo.u32 %r39, %r51, %r14;           // (tw*4)*stride_w
    mad.lo.u32 %r39, %r38, %r25, %r39;     // iw_l0
    mad.lo.u32 %r52, %r37, %r27, %r39;     // smem idx0
    add.u32 %r53, %r52, %r14;              // + stride_w
    add.u32 %r54, %r53, %r14;
    add.u32 %r55, %r54, %r14;
    cvt.u64.u32 %rd5, %r52;
    shl.b64     %rd5, %rd5, 2;
    add.u64     %rd5, %rd0, %rd5;
    ld.shared.f32 %f4, [%rd5];
    cvt.u64.u32 %rd6, %r53;
    shl.b64     %rd6, %rd6, 2;
    add.u64     %rd6, %rd0, %rd6;
    ld.shared.f32 %f5, [%rd6];
    cvt.u64.u32 %rd7, %r54;
    shl.b64     %rd7, %rd7, 2;
    add.u64     %rd7, %rd0, %rd7;
    ld.shared.f32 %f6, [%rd7];
    cvt.u64.u32 %rd8, %r55;
    shl.b64     %rd8, %rd8, 2;
    add.u64     %rd8, %rd0, %rd8;
    ld.shared.f32 %f7, [%rd8];
    add.u64     %rd5, %rd5, %rd20;
    ld.shared.f32 %f77, [%rd5];
    add.u64     %rd6, %rd6, %rd20;
    ld.shared.f32 %f78, [%rd6];
    add.u64     %rd7, %rd7, %rd20;
    ld.shared.f32 %f79, [%rd7];
    add.u64     %rd8, %rd8, %rd20;
